CREATE TABLE "ordering"."Orders"
(
 "Id" uuid NOT NULL DEFAULT gen_random_uuid(),
 "OrderNo" varchar(40) NOT NULL,
 "CustomerId" uuid NULL,
 "UserId" varchar(450) NULL,
 "ContactName" varchar(160) NOT NULL, "ContactPhone" varchar(20) NOT NULL,
 "PackageId" uuid NOT NULL, "PackageName" varchar(160) NOT NULL,
 "CategoryName" varchar(160) NOT NULL, "VariantName" varchar(160) NULL,
 "Guests" INT NOT NULL, "EventDate" DATE NOT NULL, "EventTime" TIME(0) NOT NULL,
 "EventType" varchar(160) NOT NULL, "VenueAddress" varchar(1000) NOT NULL,
 "SpecialInstructions" varchar(2000) NULL,
 "Status" varchar(24) NOT NULL DEFAULT 'Pending',
 "UnitPricePerHead" DECIMAL(12,2) NOT NULL, "UnitCostPerHead" DECIMAL(12,2) NOT NULL,
 "SubTotal" DECIMAL(12,2) NOT NULL, "AddOnTotal" DECIMAL(12,2) NOT NULL,
 "DeliveryCharge" DECIMAL(12,2) NOT NULL, "Discount" DECIMAL(12,2) NOT NULL,
 "GrandTotal" DECIMAL(12,2) NOT NULL, "TotalCost" DECIMAL(12,2) NOT NULL,
 "SnapshotJson" text NOT NULL,
 "CreatedAt" timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
 "CreatedBy" varchar(450) NULL, "UpdatedAt" timestamp without time zone NULL, "UpdatedBy" varchar(450) NULL,
 "RowVersion" bytea DEFAULT decode(replace(gen_random_uuid()::text, '-', ''), 'hex') NOT NULL,
 CONSTRAINT "PK_Orders" PRIMARY KEY ("Id"),
 CONSTRAINT "CK_Orders_Guests" CHECK ("Guests" BETWEEN 1 AND 100000),
 CONSTRAINT "CK_Orders_Status" CHECK ("Status" IN ('Pending','Confirmed','InPreparation','Dispatched','Delivered','Completed','Cancelled','Rejected')),
 CONSTRAINT "CK_Orders_Money" CHECK ("UnitPricePerHead">0 AND "UnitCostPerHead">=0 AND "SubTotal">0 AND "AddOnTotal">=0 AND "DeliveryCharge">=0 AND "Discount">=0 AND "GrandTotal">0 AND "TotalCost">=0 AND "GrandTotal"="SubTotal"+"AddOnTotal"+"DeliveryCharge"-"Discount"),
 CONSTRAINT "CK_Orders_Snapshot" CHECK (("SnapshotJson"::jsonb IS NOT NULL))
);

