CREATE VIEW "catalog"."vw_PackageCosting"
AS
SELECT
    p."Id" AS "PackageId",
    p."Name" AS "PackageName",
    p."Slug" AS "PackageSlug",
    c."Name" AS "CategoryName",
    p."SalePricePerHead" AS "SalePricePerHead",
    COALESCE((
        SELECT SUM(pi."CostPerHead")
        FROM "catalog"."PackageItems" pi
        WHERE pi."PackageId" = p."Id"
    ), 0) AS "TotalCost",
    p."SalePricePerHead" - COALESCE((
        SELECT SUM(pi."CostPerHead")
        FROM "catalog"."PackageItems" pi
        WHERE pi."PackageId" = p."Id"
    ), 0) AS "Profit",
    CASE
        WHEN p."SalePricePerHead" = 0 THEN 0
        ELSE (p."SalePricePerHead" - COALESCE((
            SELECT SUM(pi."CostPerHead")
            FROM "catalog"."PackageItems" pi
            WHERE pi."PackageId" = p."Id"
        ), 0)) / p."SalePricePerHead"
    END AS "MarginPct"
FROM "catalog"."Packages" p
JOIN "catalog"."Categories" c ON c."Id" = p."CategoryId"
WHERE p."IsDeleted" = false;

CREATE VIEW "ordering"."vw_KitchenPrep" AS
SELECT o."EventDate", j.value AS "ItemName", COALESCE(o."VariantName", 'Standard') AS "VariantName",
 SUM(o."Guests")::integer AS "TotalHeads", COUNT(*) AS "OrderCount"
FROM "ordering"."Orders" o
CROSS JOIN LATERAL jsonb_array_elements_text(o."SnapshotJson"::jsonb->'items') j(value)
WHERE o."Status" IN ('Confirmed','InPreparation')
GROUP BY o."EventDate", j.value, o."VariantName";

CREATE VIEW "reporting"."vw_OrderSummary" AS
SELECT "Id", "OrderNo", "EventDate", "Status", "PackageName", "CategoryName", "Guests",
 "GrandTotal", "TotalCost", "GrandTotal"-"TotalCost" AS "Profit",
 COALESCE((SELECT SUM(p."Amount") FROM "ordering"."Payments" p WHERE p."OrderId"=o."Id"),0) AS "PaidAmount"
FROM "ordering"."Orders" o;



MERGE INTO "identity"."Permissions" AS t
USING (VALUES
