    ('identity.user.manage',  'identity',   'Create/edit staff users'),
    ('identity.role.view',    'identity',   'View roles'),
    ('identity.role.manage',  'identity',   'Manage roles & grants'),
    ('identity.audit.view',   'identity',   'View audit log'),
    ('nav.menu.view',         'nav',        'View menus'),
    ('nav.menu.manage',       'nav',        'Manage dynamic menus'),
    ('catalog.category.view', 'catalog',    'View categories'),
    ('catalog.category.edit', 'catalog',    'Edit categories'),
    ('catalog.package.view',  'catalog',    'View packages'),
    ('catalog.package.edit',  'catalog',    'Edit packages/items/prices'),
    ('catalog.costing.view',  'catalog',    'View costs & margins'),
    ('ordering.order.view',   'ordering',   'View orders'),
    ('ordering.pricing.view', 'ordering',   'View booking sale amounts and payments'),
    ('ordering.order.manage', 'ordering',   'Create/confirm/cancel orders'),
    ('ordering.kitchen.view', 'ordering',   'Kitchen prep sheet (no money)'),
    ('ordering.payment.record', 'ordering', 'Record manual payments'),
    ('customers.view',        'customers',  'View customers'),
    ('customers.manage',      'customers',  'Manage customers'),
