    ('content.edit',          'content',    'Edit CMS content'),
    ('reporting.view',        'reporting',  'View dashboards & reports')
) AS s ("Code", "Module", "Description")
ON t."Code" = s."Code"
WHEN MATCHED THEN UPDATE SET "Module" = s."Module", "Description" = s."Description"
WHEN NOT MATCHED THEN INSERT ("Code", "Module", "Description") VALUES (s."Code", s."Module", s."Description");


MERGE INTO "identity"."Roles" AS t
USING (VALUES
    ('SuperAdmin', 'SUPERADMIN', 'Full system access incl. roles/permissions/menu', 1),
    ('Admin',      'ADMIN',      'Owner: everything except system settings; sees costing', 0),
    ('Manager',    'MANAGER',    'Orders/customers/inquiries/reviews/content; sees costing', 0),
    ('Kitchen',    'KITCHEN',    'Prep sheet + status to InPreparation/Dispatched; no money', 0),
    ('Sales',      'SALES',      'Orders on behalf of customers + inquiries; sale prices only', 0),
    ('Customer',   'CUSTOMER',   'Public + customer endpoints only', 0)
) AS s ("Name", "NormalizedName", "Description", "IsSystem")
ON t."NormalizedName" = s."NormalizedName"
WHEN MATCHED THEN UPDATE SET "Name" = s."Name", "Description" = s."Description", "IsSystem" = (s."IsSystem"::integer <> 0), "UpdatedAt" = timezone('UTC', now())
WHEN NOT MATCHED THEN INSERT ("Id", "Name", "NormalizedName", "Description", "IsSystem") VALUES (gen_random_uuid()::text, s."Name", s."NormalizedName", s."Description", (s."IsSystem"::integer <> 0));



MERGE INTO "identity"."RolePermissions" AS t
USING (
    SELECT r."Id" AS RoleId, p."Id" AS PermissionId
    FROM "identity"."Roles" r CROSS JOIN "identity"."Permissions" p
    WHERE r."NormalizedName" IN ('SUPERADMIN', 'ADMIN')
    UNION
    SELECT r."Id", p."Id" FROM "identity"."Roles" r
    JOIN "identity"."Permissions" p ON p."Code" IN (
        'catalog.category.view', 'catalog.package.view', 'catalog.costing.view',
        'ordering.order.view', 'ordering.order.manage', 'ordering.pricing.view', 'ordering.kitchen.view',
        'customers.view', 'customers.manage',
        'engagement.inquiry.view', 'engagement.inquiry.manage', 'engagement.review.moderate',
        'content.view', 'content.edit', 'reporting.view', 'nav.menu.view')
    WHERE r."NormalizedName" = 'MANAGER'
    UNION
    SELECT r."Id", p."Id" FROM "identity"."Roles" r
    JOIN "identity"."Permissions" p ON p."Code" IN ('ordering.kitchen.view', 'ordering.order.view', 'nav.menu.view')
    WHERE r."NormalizedName" = 'KITCHEN'
    UNION
    SELECT r."Id", p."Id" FROM "identity"."Roles" r
    JOIN "identity"."Permissions" p ON p."Code" IN (
        'catalog.category.view', 'catalog.package.view',
        'ordering.order.view', 'ordering.order.manage', 'ordering.pricing.view',
        'customers.view', 'customers.manage',
        'engagement.inquiry.view', 'engagement.inquiry.manage', 'nav.menu.view')
    WHERE r."NormalizedName" = 'SALES'
) AS s (RoleId, PermissionId)
ON t."RoleId" = s.roleid AND t."PermissionId" = s.permissionid
WHEN NOT MATCHED THEN INSERT ("RoleId", "PermissionId") VALUES (s.roleid, s.permissionid);

DELETE FROM "identity"."RolePermissions" t
WHERE NOT EXISTS (
    SELECT 1 FROM (
        SELECT r."Id" AS RoleId, p."Id" AS PermissionId
        FROM "identity"."Roles" r CROSS JOIN "identity"."Permissions" p
        WHERE r."NormalizedName" IN ('SUPERADMIN', 'ADMIN')
        UNION
        SELECT r."Id", p."Id" FROM "identity"."Roles" r
        JOIN "identity"."Permissions" p ON p."Code" IN (
            'catalog.category.view', 'catalog.package.view', 'catalog.costing.view',
            'ordering.order.view', 'ordering.order.manage', 'ordering.pricing.view', 'ordering.kitchen.view',
            'customers.view', 'customers.manage',
            'engagement.inquiry.view', 'engagement.inquiry.manage', 'engagement.review.moderate',
            'content.view', 'content.edit', 'reporting.view', 'nav.menu.view')
        WHERE r."NormalizedName" = 'MANAGER'
        UNION
        SELECT r."Id", p."Id" FROM "identity"."Roles" r
        JOIN "identity"."Permissions" p ON p."Code" IN ('ordering.kitchen.view', 'ordering.order.view', 'nav.menu.view')
        WHERE r."NormalizedName" = 'KITCHEN'
        UNION
        SELECT r."Id", p."Id" FROM "identity"."Roles" r
        JOIN "identity"."Permissions" p ON p."Code" IN (
            'catalog.category.view', 'catalog.package.view',
            'ordering.order.view', 'ordering.order.manage', 'ordering.pricing.view',
            'customers.view', 'customers.manage',
            'engagement.inquiry.view', 'engagement.inquiry.manage', 'nav.menu.view')
        WHERE r."NormalizedName" = 'SALES'
    ) d WHERE d.RoleId = t."RoleId" AND d.PermissionId = t."PermissionId"
)
AND EXISTS (SELECT 1 FROM "identity"."Roles" r WHERE r."Id" = t."RoleId" AND r."NormalizedName" IN ('MANAGER', 'KITCHEN', 'SALES'));


