UPDATE "nav"."MenuItems" c SET "ParentId" = p."Id"
FROM "nav"."MenuItems" p
WHERE ((c."Key" = 'orders.all' OR c."Key" = 'orders.calendar' OR c."Key" = 'orders.kitchen') AND p."Key" = 'orders'
   OR (c."Key" = 'catalog.packages' OR c."Key" = 'catalog.costing') AND p."Key" = 'catalog'
   OR (c."Key" IN ('engagement.reviews','engagement.inbox')) AND p."Key" = 'engagement'
   OR (c."Key" = 'admin.menu' OR c."Key" = 'admin.audit') AND p."Key" = 'admin')
AND c."ParentId" IS NULL AND c."Key" <> p."Key";





